    deepExplanation: "Step 1 — Build the matching rule.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nfunction isValidParentheses(value: string): boolean {\n  const stack: string[] = [];\n\n  for (let i = 0; i < value.length; i++) {\n    const ch = value[i]!;\n\n    if (ch === \"(\" || ch === \"[\" || ch === \"{\") {\n      stack.push(ch);\n      continue;\n    }\n\n    const top = stack.pop();\n\n    if (\n      (ch === \")\" && top !== \"(\") ||\n      (ch === \"]\" && top !== \"[\") ||\n      (ch === \"}\" && top !== \"{\")\n    ) {\n      return false;\n    }\n  }\n\n  return stack.length === 0;\n}\n```\n\nWITH BUILT-IN:\n```ts\nfunction isValidParenthesesUsingMap(value: string): boolean {\n  const stack: string[] = [];\n  const matching = new Map<string, string>([\n    [\")\", \"(\"],\n    [\"]\", \"[\"],\n    [\"}\", \"{\"],\n  ]);\n\n  for (const ch of value) {\n    if (!matching.has(ch)) {\n      stack.push(ch);\n      continue;\n    }\n\n    if (stack.pop() !== matching.get(ch)) return false;\n  }\n\n  return stack.length === 0;\n}\n```\n\nStep 2 — Example:\n`{[()]}`\npush `{`\npush `[`\npush `(`\n`)` matches `(`\n`]` matches `[`\n`}` matches `{`\n→ true.\n\n`([)]` → `)` expects `(` but top is `[` → false.\n\nStep 3 — Complexity:\nO(n) time and O(n) worst-case auxiliary space.",
