    deepExplanation: "Step 1 — Maintain two stacks: undo and redo.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nclass UndoRedoHistory<T> {\n  private readonly undoStack: T[] = [];\n  private readonly redoStack: T[] = [];\n\n  constructor(private current: T) {}\n\n  apply(nextState: T): void {\n    this.undoStack.push(this.current);\n    this.current = nextState;\n    this.redoStack.length = 0;\n  }\n\n  undo(): T {\n    if (this.undoStack.length === 0) return this.current;\n\n    this.redoStack.push(this.current);\n    this.current = this.undoStack.pop()!;\n    return this.current;\n  }\n\n  redo(): T {\n    if (this.redoStack.length === 0) return this.current;\n\n    this.undoStack.push(this.current);\n    this.current = this.redoStack.pop()!;\n    return this.current;\n  }\n\n  getState(): T {\n    return this.current;\n  }\n}\n```\n\nWITH BUILT-IN:\n```ts\nclass SimpleHistory {\n  private readonly undoStack: string[] = [];\n  private readonly redoStack: string[] = [];\n\n  constructor(private current: string) {}\n\n  apply(next: string): void {\n    this.undoStack.push(this.current);\n    this.current = next;\n    this.redoStack.length = 0;\n  }\n\n  undo(): string {\n    if (this.undoStack.length) {\n      this.redoStack.push(this.current);\n      this.current = this.undoStack.pop()!;\n    }\n    return this.current;\n  }\n\n  redo(): string {\n    if (this.redoStack.length) {\n      this.undoStack.push(this.current);\n      this.current = this.redoStack.pop()!;\n    }\n    return this.current;\n  }\n}\n```\n\nStep 2 — Example:\nA → B → C\nundo → B\nundo → A\nredo → B\napply D from B → redo history is cleared.\n\nStep 3 — Complexity:\nEach operation is O(1), but storing complete states may require O(number of history states × state size).",
